	/** 
	 * jumpstart the process by instantiating2 Placement
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		placementId = PlacementService.getPlacementInstance()
		.createPlacement( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PlacementService.getPlacementInstance()
				.createPlacement( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.placementSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Placement : " + successValue.getPlacementId());
							  if (successValue.getPlacementId().equals(placementId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPlacementList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Placement test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on placement consumed")
					);
			subscriber.placementSubscribe( placementId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Placement : " + successValue.getPlacementId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPlacementList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on placement for placementId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Placement. 
	 */
	protected Placement read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Placement" );

		Placement entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Placement with primary key" );
		msg.append( placementId );
		
		PlacementFetchOneSummary fetchOneSummary = new PlacementFetchOneSummary( placementId );

		try {
			entity = PlacementService.getPlacementInstance().getPlacement( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Placement " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Placement.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Placement." );

		StringBuilder msg = new StringBuilder( "Failed to update a Placement : " );        
		Placement entity = read();
		UpdatePlacementCommand command = generateUpdateCommand();
		command.setPlacementId(entity.getPlacementId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Placement." );

			// for use later on...
			placementId = entity.getPlacementId();

			PlacementService proxy = PlacementService.getPlacementInstance();  

			proxy.updatePlacement( command ).get();

			LOGGER.info( "-- Successfully saved Placement - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + placementId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Placement.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Placement." );

		Placement entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Placement with id " + placementId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Placement with id " + placementId );

			throw e;
		}

		try{
			PlacementService.getPlacementInstance().delete( new DeletePlacementCommand( entity.getPlacementId() ) ).get();
			LOGGER.info( "-- Successfully deleted Placement with id " + placementId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Placement with id " + placementId );

			throw e;
		}
	}

	/**
	 * get all Placements.
	 */
	protected List<Placement> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Placements:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Placement : " );        
		List<Placement> collection  = new ArrayList<>();

		try {
			// call the static get method on the PlacementService
			collection = PlacementService.getPlacementInstance().getAllPlacement();
			assertNotNull( collection, "An Empty collection of Placement was incorrectly returned.");
			
			// Now print out the values
			Placement entity = null;            
			Iterator<Placement> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPlacementId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

